15	
16	import java.util.Objects;
17	import java.util.concurrent.*;
18	
19	import io.reactivex.rxjava4.annotations.*;
20	import io.reactivex.rxjava4.core.StreamSink;
21	import io.reactivex.rxjava4.exceptions.Exceptions;
22	import io.reactivex.rxjava4.functions.Function;
23	
24	/**
25	 * Creates a {@link StreamSink} via lambda callbacks for {@link #next(Object)} and
26	 * {@link #finish(Throwable)}.
27	 * @param <T> the element type of the stream
28	 * @param onNext the callback for the {@code next} method
29	 * @param onFinish the callback for the {@code finish} method
30	 * @since 4.0.0
31	 */
32	public record StreamSinkLambda<@NonNull T>(
33	        @NonNull Function<? super T, ? extends CompletionStage<Boolean>> onNext,
34	        @NonNull Function<? super Throwable, ? extends CompletionStage<Void>> onFinish
35	) implements StreamSink<T> {
36	
37	    @Override
38	    public @NonNull CompletionStage<Boolean> next(@NonNull T item) {
39	        try {
40	            return Objects.requireNonNull(onNext.apply(item), "onNext returned a null CompletionStage");
41	        } catch (Throwable ex) {
42	            Exceptions.throwIfFatal(ex);
43	            return CompletableFuture.failedStage(ex);
44	        }
45	    }
46	
47	    @Override
48	    public @NonNull CompletionStage<Void> finish(@Nullable Throwable throwable) {
49	        try {
50	            return Objects.requireNonNull(onFinish.apply(throwable), "onFinish returned a null CompletionStage");
51	        } catch (Throwable ex) {
52	            Exceptions.throwIfFatal(ex);
53	            if (throwable != null) {
54	                ex.addSuppressed(throwable);
55	            }
56	            return CompletableFuture.failedStage(ex);
57	        }
58	    }
59	}
