19	import io.reactivex.rxjava4.exceptions.Exceptions;
20	import io.reactivex.rxjava4.plugins.RxJavaPlugins;
21	
22	/**
23	 * Allows lifting operators into a chain of Publishers.
24	 *
25	 * <p>By having a concrete Publisher as lift, operator fusing can now identify
26	 * both the source and the operation inside it via casting, unlike the lambda version of this.
27	 *
28	 * @param <T> the upstream value type
29	 * @param <R> the downstream parameter type
30	 */
31	public final class FlowableLift<R, T> extends AbstractFlowableWithUpstream<T, R> {
32	    /** The actual operator. */
33	    final FlowableOperator<? extends R, ? super T> operator;
34	
35	    public FlowableLift(Flowable<T> source, FlowableOperator<? extends R, ? super T> operator) {
36	        super(source);
37	        this.operator = operator;
38	    }
39	
40	    @Override
41	    public void subscribeActual(Subscriber<? super R> s) {
42	        try {
43	            Subscriber<? super T> st = operator.apply(s);
44	
45	            if (st == null) {
46	                throw new NullPointerException("Operator " + operator + " returned a null Subscriber");
47	            }
48	
49	            source.subscribe(st);
50	        } catch (NullPointerException e) { // NOPMD
51	            throw e;
52	        } catch (Throwable e) {
53	            Exceptions.throwIfFatal(e);
54	            // can't call onError because no way to know if a Subscription has been set or not
55	            // can't call onSubscribe because the call might have set a Subscription already
56	            RxJavaPlugins.onError(e);
57	
58	            NullPointerException npe = new NullPointerException("Actually not, but can't throw other exceptions due to RS");
59	            npe.initCause(e);
60	            throw npe;
61	        }
62	    }
63	}
