14	package io.reactivex.rxjava4.internal.jdk8;
15	
16	import java.io.Serial;
17	import java.util.Iterator;
18	import java.util.Objects;
19	import java.util.concurrent.atomic.AtomicLong;
20	import java.util.stream.Stream;
21	
22	import static java.util.concurrent.Flow.*;
23	
24	import io.reactivex.rxjava4.annotations.*;
25	import io.reactivex.rxjava4.core.Flowable;
26	import io.reactivex.rxjava4.exceptions.Exceptions;
27	import io.reactivex.rxjava4.internal.subscriptions.*;
28	import io.reactivex.rxjava4.internal.util.BackpressureHelper;
29	import io.reactivex.rxjava4.operators.ConditionalSubscriber;
30	import io.reactivex.rxjava4.operators.QueueSubscription;
31	import io.reactivex.rxjava4.plugins.RxJavaPlugins;
32	
33	/**
34	 * Wraps a {@link Stream} and emits its values as a Flowable sequence.
35	 * @param <T> the element type of the Stream
36	 * @since 3.0.0
37	 */
38	public final class FlowableFromStream<T> extends Flowable<T> {
39	
40	    final Stream<T> stream;
41	
42	    public FlowableFromStream(Stream<T> stream) {
43	        this.stream = stream;
44	    }
45	
46	    @Override
47	    protected void subscribeActual(Subscriber<? super T> s) {
48	        subscribeStream(s, stream);
49	    }
50	
51	    /**
52	     * Subscribes to the Stream by picking the normal or conditional stream Subscription implementation.
53	     * @param <T> the element type of the flow
54	     * @param s the subscriber to drive
55	     * @param stream the sequence to consume
56	     */
57	    public static <T> void subscribeStream(Subscriber<? super T> s, Stream<T> stream) {
58	        Iterator<T> iterator;
59	        try {
60	            iterator = stream.iterator();
61	
62	            if (!iterator.hasNext()) {
63	                EmptySubscription.complete(s);
64	                closeSafely(stream);
65	                return;
66	            }
67	        } catch (Throwable ex) {
68	            Exceptions.throwIfFatal(ex);
69	            EmptySubscription.error(ex, s);
70	            closeSafely(stream);
71	            return;
72	        }
73	
74	        if (s instanceof ConditionalSubscriber) {
75	            s.onSubscribe(new StreamConditionalSubscription<>((ConditionalSubscriber<? super T>)s, iterator, stream));
76	        } else {
77	            s.onSubscribe(new StreamSubscription<>(s, iterator, stream));
78	        }
79	    }
80	
81	    static void closeSafely(AutoCloseable c) {
82	        try {
83	            c.close();
84	        } catch (Throwable ex) {
85	            Exceptions.throwIfFatal(ex);
86	            RxJavaPlugins.onError(ex);
87	        }
88	    }
89	
90	    abstract static class AbstractStreamSubscription<T> extends AtomicLong implements QueueSubscription<T> {
91	
92	        @Serial
93	        private static final long serialVersionUID = -9082954702547571853L;
94	
95	        Iterator<T> iterator;
96	
97	        AutoCloseable closeable;
98	
99	        volatile boolean cancelled;
100	
101	        boolean once;
102	
103	        AbstractStreamSubscription(Iterator<T> iterator, AutoCloseable closeable) {
104	            this.iterator = iterator;
105	            this.closeable = closeable;
106	        }
107	
108	        @Override
109	        public void request(long n) {
110	            if (SubscriptionHelper.validate(n)) {
111	                if (BackpressureHelper.add(this, n) == 0L) {
112	                    run(n);
113	                }
114	            }
115	        }
116	
117	        abstract void run(long n);
118	
119	        @Override
120	        public void cancel() {
121	            cancelled = true;
122	            request(1L);
123	        }
124	
125	        @Override
126	        public int requestFusion(int mode) {
127	            if ((mode & SYNC) != 0) {
128	                lazySet(Long.MAX_VALUE);
129	                return SYNC;
130	            }
131	            return NONE;
132	        }
133	
134	        @Override
135	        public boolean offer(@NonNull T value) {
136	            throw new UnsupportedOperationException();
137	        }
138	
139	        @Override
140	        public boolean offer(@NonNull T v1, @NonNull T v2) {
141	            throw new UnsupportedOperationException();
142	        }
143	
144	        @Nullable
145	        @Override
146	        public T poll() {
147	            if (iterator == null) {
148	                return null;
149	            }
150	            if (!once) {
151	                once = true;
152	            } else {
153	                if (!iterator.hasNext()) {
154	                    clear();
155	                    return null;
156	                }
157	            }
158	            return Objects.requireNonNull(iterator.next(), "The Stream's Iterator.next() returned a null value");
159	        }
160	
161	        @Override
162	        public boolean isEmpty() {
163	            Iterator<T> it = iterator;
164	            if (it != null) {
165	                if (!once || it.hasNext()) {
166	                    return false;
167	                }
168	                clear();
169	            }
170	            return true;
171	        }
172	
173	        @Override
174	        public void clear() {
175	            iterator = null;
176	            AutoCloseable c = closeable;
177	            closeable = null;
178	            if (c != null) {
179	                closeSafely(c);
180	            }
181	        }
182	    }
183	
184	    static final class StreamSubscription<T> extends AbstractStreamSubscription<T> {
185	
186	        @Serial
187	        private static final long serialVersionUID = -9082954702547571853L;
188	
189	        final Subscriber<? super T> downstream;
190	
191	        StreamSubscription(Subscriber<? super T> downstream, Iterator<T> iterator, AutoCloseable closeable) {
192	            super(iterator, closeable);
193	            this.downstream = downstream;
194	        }
195	
196	        @Override
197	        public void run(long n) {
198	            long emitted = 0L;
199	            Iterator<T> iterator = this.iterator;
200	            Subscriber<? super T> downstream = this.downstream;
201	
202	            for (;;) {
203	
204	                if (cancelled) {
205	                    clear();
206	                    break;
207	                } else {
208	                    T next;
209	                    try {
210	                        next = Objects.requireNonNull(iterator.next(), "The Stream's Iterator returned a null value");
211	                    } catch (Throwable ex) {
212	                        Exceptions.throwIfFatal(ex);
213	                        downstream.onError(ex);
214	                        cancelled = true;
215	                        continue;
216	                    }
217	
218	                    downstream.onNext(next);
219	
220	                    if (cancelled) {
221	                        continue;
222	                    }
223	
224	                    try {
225	                        if (!iterator.hasNext()) {
226	                            downstream.onComplete();
227	                            cancelled = true;
228	                            continue;
229	                        }
230	                    } catch (Throwable ex) {
231	                        Exceptions.throwIfFatal(ex);
232	                        downstream.onError(ex);
233	                        cancelled = true;
234	                        continue;
235	                    }
236	
237	                    if (++emitted != n) {
238	                        continue;
239	                    }
240	                }
241	
242	                n = get();
243	                if (emitted == n) {
244	                    if (compareAndSet(n, 0L)) {
245	                        break;
246	                    }
247	                    n = get();
248	                }
249	            }
250	        }
251	    }
252	
253	    static final class StreamConditionalSubscription<T> extends AbstractStreamSubscription<T> {
254	
255	        @Serial
256	        private static final long serialVersionUID = -9082954702547571853L;
257	
258	        final ConditionalSubscriber<? super T> downstream;
259	
260	        StreamConditionalSubscription(ConditionalSubscriber<? super T> downstream, Iterator<T> iterator, AutoCloseable closeable) {
261	            super(iterator, closeable);
262	            this.downstream = downstream;
263	        }
264	
265	        @Override
266	        public void run(long n) {
267	            long emitted = 0L;
268	            Iterator<T> iterator = this.iterator;
269	            ConditionalSubscriber<? super T> downstream = this.downstream;
270	
271	            for (;;) {
272	
273	                if (cancelled) {
274	                    clear();
275	                    break;
276	                } else {
277	                    T next;
278	                    try {
279	                        next = Objects.requireNonNull(iterator.next(), "The Stream's Iterator returned a null value");
280	                    } catch (Throwable ex) {
281	                        Exceptions.throwIfFatal(ex);
282	                        downstream.onError(ex);
283	                        cancelled = true;
284	                        continue;
285	                    }
286	
287	                    if (downstream.tryOnNext(next)) {
288	                        emitted++;
289	                    }
290	
291	                    if (cancelled) {
292	                        continue;
293	                    }
294	
295	                    try {
296	                        if (!iterator.hasNext()) {
297	                            downstream.onComplete();
298	                            cancelled = true;
299	                            continue;
300	                        }
301	                    } catch (Throwable ex) {
302	                        Exceptions.throwIfFatal(ex);
303	                        downstream.onError(ex);
304	                        cancelled = true;
305	                        continue;
306	                    }
307	
308	                    if (emitted != n) {
309	                        continue;
310	                    }
311	                }
312	
313	                n = get();
314	                if (emitted == n) {
315	                    if (compareAndSet(n, 0L)) {
316	                        break;
317	                    }
318	                    n = get();
319	                }
320	            }
321	        }
322	    }
323	}
